def f(w):
    return ''.join(chr(ord(c)+(-1 if i%2==0 else 1)) for i,c in enumerate(w))
assert f('TABU')=='SBAV' and f('TANK')=='SBML'
o={'A':'SMBH','B':'SBMH','C':'SBHM','D':'SMHB'}
assert f('TAIL')==o['C']
for k in 'ABD': assert f('TAIL')!=o[k]
